The program reads up to 3·10^5 characters in total, uses only O(1) additional memory besides the input string, and prints each answer on its own line exactly as required.

/*
   Chess Tournament Pairing – minimal rated-vs-rated opponents
   Let total players be 2N and X of them rated.
   First pair every rated player with an unrated one. That uses up min(X,2N-X) rated players.
   Any remaining rated players (if X>N) must face another rated player, so each of them and their opponent both
   contribute to the final count. Mathematically the number of rated players that will still face a rated
   opponent is max(0, 2*X – 2*N).
*/
#include <stdio.h>

int main(void) {
    int T;
    if (scanf("%d", &T) != 1) return 0;          // number of test cases
    while (T--) {
        int N, X;
        scanf("%d %d", &N, &X);
        int answer = 0;
        int diff = 2 * X - 2 * N;                 // 2*(X – N)
        if (diff > 0) answer = diff;              // only positive part counts
        printf("%d\n", answer);
    }
    return 0;
}

