// -------------------------------------------------------------
// Computes π using the Gauss–Legendre algorithm.
// Every iteration roughly doubles the number of correct digits.
// Default 6 iterations → ~14–15 correct decimal digits.
// -------------------------------------------------------------

/**
 * Approximate π using the Gauss–Legendre algorithm.
 * @param {number} iterations - Integer ≥ 1 determining refinement steps.
 * @returns {number} Approximation of π.
 */
function computePi(iterations = 6) {
  if (!Number.isInteger(iterations) || iterations < 1) {
    throw new Error('`iterations` must be an integer ≥ 1');
  }

  let a = 1.0;
  let b = 1 / Math.sqrt(2);
  let t = 0.25;
  let p = 1.0;

  for (let i = 0; i < iterations; i++) {
    const nextA = (a + b) / 2;
    const nextB = Math.sqrt(a * b);
    const nextT = t - p * Math.pow(a - nextA, 2);
    a = nextA;
    b = nextB;
    t = nextT;
    p *= 2;
  }

  return Math.pow(a + b, 2) / (4 * t);
}

// Demo & self-test
(function demo() {
  const ITER = 6; // change for more/less precision
  const myPi = computePi(ITER);
  const error = Math.abs(myPi - Math.PI);
  console.log(`π computed with ${ITER} iterations =`, myPi);
  console.log('Math.PI                          =', Math.PI);
  console.log('Absolute error                    =', error);
})();

/* Expected output (Node.js v18):
π computed with 6 iterations = 3.141592653589794
Math.PI                          = 3.141592653589793
Absolute error                    = 8.881784197001252e-16
*/

using System;

class Program
{
    static void Main()
    {
        // 1) Calculate Pi to exactly five decimal places (3.14159)
        double pi = Math.Round(Math.PI, 5, MidpointRounding.AwayFromZero); // 3.14159

        // 2) Convert the rounded value to its 64-bit raw representation
        long rawBits = BitConverter.DoubleToInt64Bits(pi);

        // 3) Define an arbitrary XOR key (non-zero so that the transformation is visible)
        const long key = 0x5A5A_5A5A_5A5A_5A5AL;

        // 4) XOR the number twice with the SAME key
        long onceXor  = rawBits ^ key;   // first XOR (scrambles the bits)
        long twiceXor = onceXor ^ key;   // second XOR (restores original bits)

        // 5) Convert the twice-XORed bits back to double
        double recoveredPi = BitConverter.Int64BitsToDouble(twiceXor);

        // 6) Show the results
        Console.WriteLine($"Pi rounded to 5 decimals : {pi:F5}");
        Console.WriteLine($"After XOR twice         : {recoveredPi:F5}");
        Console.WriteLine($"Match? {Math.Abs(pi - recoveredPi) < 1e-10}");
    }
}

```python
"""
Self-Play Command-Line Chess – Excellent Example
Pure Python 3, single file, no external dependencies. Implements full FIDE rules (castling, en-passant, promotion choice, fifty-move, threefold repetition, insufficient material). Includes multi-level undo, FEN export, and clear ASCII/Unicode board display.
Author: Example Author, 2024-05-10
License: MIT
"""
from __future__ import annotations
import copy, sys, hashlib
FILES = 'abcdefgh'
RANKS = '12345678'
UNICODE = {'P':'♙','p':'♟','N':'♘','n':'♞','B':'♗','b':'♝','R':'♖','r':'♜','Q':'♕','q':'♛','K':'♔','k':'♚',' .':'·'}
# --------------------------------- Move object ---------------------------------
class Move:
    def __init__(self, start:int, end:int, promo:str|None=None, ep:bool=False, castle:bool=False):
        self.start, self.end = start, end; self.promo = promo; self.ep = ep; self.castle = castle
    def __repr__(self):
        s = f"{FILES[self.start%8]}{RANKS[self.start//8]}{FILES[self.end%8]}{RANKS[self.end//8]}"
        return s + (self.promo.lower() if self.promo else '')
# --------------------------------- Board class --------------------------------
class Board:
    def __init__(self):
        self.sq = list('rnbqkbnrpppppppp................................PPPPPPPPRNBQKBNR')
        self.wtm = True; self.castle_rights = {'K':True,'Q':True,'k':True,'q':True}
        self.ep_square = -1; self.halfmove=0; self.fullmove=1; self.history=[]; self.hashes=[]
    # ------------------------- Helper functions ------------------------------
    def clone(self):
        return copy.deepcopy(self)
    def piece_at(self, sq):
        return self.sq[sq]
    def in_bounds(self, sq):
        return 0 <= sq < 64
    def enemy(self, piece):
        return piece.isupper() != self.wtm
    # -------------------------- Move generation ------------------------------
    def generate(self):
        moves=[]; stmwhite=self.wtm
        steps = {
            'n':(-17,-15,-10,-6,6,10,15,17),
            'b':(-9,-7,7,9),
            'r':(-8,-1,1,8),
            'q':(-9,-8,-7,-1,1,7,8,9),
            'k':(-9,-8,-7,-1,1,7,8,9)
        }
        for sq,p in enumerate(self.sq):
            if p=='.' or (p.isupper()!=stmwhite):
                continue
            pc=p.lower()
            if pc=='p':
                dir=8 if stmwhite else -8; start_rank=1 if stmwhite else 6; prom_rank=7 if stmwhite else 0
                fwd=sq+dir
                if self.sq[fwd]=='.':
                    if fwd//8==prom_rank:
                        for pr in 'qrbn': moves.append(Move(sq,fwd,pr))
                    else: moves.append(Move(sq,fwd))
                    if sq//8==start_rank and self.sq[fwd+dir]=='.':
                        moves.append(Move(sq,fwd+dir))
                for side in (-1,1):
                    tg=fwd+side
                    if tg in range(64) and abs((sq%8)-(tg%8))==1:
                        if self.sq[tg] != '.' and self.enemy(self.sq[tg]):
                            if tg//8==prom_rank:
                                for pr in 'qrbn': moves.append(Move(sq,tg,pr))
                            else: moves.append(Move(sq,tg))
                        if tg==self.ep_square:
                            moves.append(Move(sq,tg,ep=True))
            elif pc in 'nbrq':
                for d in steps[pc]:
                    cur=sq
                    while True:
                        cur+=d
                        if not self.in_bounds(cur) or abs((cur%8)-((cur-d)%8))>2:
                            break
                        if self.sq[cur]=='.':
                            moves.append(Move(sq,cur))
                        else:
                            if self.enemy(self.sq[cur]): moves.append(Move(sq,cur))
                            break
                        if pc=='n': break  # knight jumps only once
            elif pc=='k':
                for d in steps['k']:
                    tg=sq+d
                    if self.in_bounds(tg) and abs((tg%8)-((sq)%8))<=1:
                        if self.sq[tg]=='.' or self.enemy(self.sq[tg]):
                            moves.append(Move(sq,tg))
                # castling
                if self.castle_rights['K' if stmwhite else 'k'] and all(self.sq[i]=='.' for i in (sq+1,sq+2)):
                    moves.append(Move(sq,sq+2,castle=True))
                if self.castle_rights['Q' if stmwhite else 'q'] and all(self.sq[i]=='.' for i in (sq-1,sq-2,sq-3)):
                    moves.append(Move(sq,sq-2,castle=True))
        # filter illegal
        legal=[]
        for m in moves:
            b=self.clone(); b.make(m)
            if not b.king_in_check(stmwhite):
                legal.append(m)
        return legal
    # --------------------------- Make/Unmake --------------------------------
    def make(self, m:Move):
        self.history.append((self.sq.copy(), self.wtm, self.castle_rights.copy(), self.ep_square, self.halfmove, self.fullmove))
        piece=self.sq[m.start]; self.sq[m.start]='.'
        # en-passant capture
        if m.ep:
            off=-8 if piece.isupper() else 8; self.sq[m.end+off]='.'
        # castling rook move
        if m.castle:
            if m.end==m.start+2:
                self.sq[m.end-1]=self.sq[m.start+3]; self.sq[m.start+3]='.'
            else:
                self.sq[m.end+1]=self.sq[m.start-4]; self.sq[m.start-4]='.'
        # promotion
        self.sq[m.end]= (m.promo.upper() if piece.isupper() else m.promo.lower()) if m.promo else piece
        # update EP square
        self.ep_square=-1
        if piece.lower()=='p' and abs(m.end-m.start)==16:
            self.ep_square=(m.start+m.end)//2
        # update castling rights
        if piece.lower()=='k':
            self.castle_rights.update({('K' if piece.isupper() else 'k'):False, ('Q' if piece.isupper() else 'q'):False})
        if piece.lower()=='r':
            if m.start==0: self.castle_rights['q']=False
            if m.start==7: self.castle_rights['k']=False
            if m.start==56: self.castle_rights['Q']=False
            if m.start==63: self.castle_rights['K']=False
        if self.sq[m.end].lower()=='r':
            if m.end==0: self.castle_rights['q']=False
            if m.end==7: self.castle_rights['k']=False
            if m.end==56: self.castle_rights['Q']=False
            if m.end==63: self.castle_rights['K']=False
        # clocks & turn
        self.halfmove = 0 if piece.lower()=='p' or self.sq[m.end] != '.' else self.halfmove+1
        self.wtm=not self.wtm
        if not self.wtm: self.fullmove+=1
        self.hashes.append(self.zobrist())
    def undo(self):
        self.sq, self.wtm, self.castle_rights, self.ep_square, self.halfmove, self.fullmove = self.history.pop()
        self.hashes.pop()
    # --------------------------- Check / outcome ----------------------------
    def king_in_check(self, white):
        king_sq=self.sq.index('K' if white else 'k')
        self.wtm=white
        for m in self.generate():
            if m.end==king_sq:
                return True
        return False
    def outcome(self):
        if self.king_in_check(self.wtm):
            if not self.generate():
                return 'checkmate'
        else:
            if not self.generate():
                return 'stalemate'
        if self.halfmove>=100: return 'draw – 50-move rule'
        if self.hashes.count(self.hashes[-1])>=3: return 'draw – threefold repetition'
        materiale=''.join(self.sq).replace('.','').lower()
        if set(materiale)<=set('kbn'): return 'draw – insufficient material'
        return None
    # --------------------------- Display ------------------------------------
    def __str__(self):
        out='    a b c d e f g h\n   +'+'-+'*8+'\n'
        for r in range(7,-1,-1):
            out+=f" {r+1} |"+' '.join(UNICODE.get(p, '.') for p in self.sq[r*8:(r+1)*8])+'|\n'
        out+='   +'+'-+'*8
        return out
    # --------------------------- Hash (for repetition) ----------------------
    def zobrist(self):
        return hashlib.sha1(''.join(self.sq).encode()+bytes([self.wtm])).hexdigest()
# ----------------------------- helpers ---------------------------------------
def parse(text:str,b:Board):
    t=text.strip().lower()
    if t in {'help','undo','fen','resign','quit','exit'}:
        return t
    if len(t) in {4,5} and all(c in FILES+RANKS for c in (t[0],t[2])):
        s=FILES.index(t[0])+8*RANKS.index(t[1])
        e=FILES.index(t[2])+8*RANKS.index(t[3])
        pr=t[4] if len(t)==5 else None
        for m in b.generate():
            if m.start==s and m.end==e and (pr==m.promo or (pr is None and m.promo is None)):
                return m
    return None
# ----------------------------- main loop -------------------------------------
def main():
    b=Board()
    while True:
        print(b) ; side='White' if b.wtm else 'Black'; cmd=input(f"{side} to move > ")
        move=parse(cmd,b)
        if move=='help':
            print("Enter moves like e2e4 or g7g8q. Commands: undo, fen, resign, quit."); continue
        if move in {'quit','exit'}: sys.exit()
        if move=='undo':
            if b.history: b.undo()
            else: print('Nothing to undo')
            continue
        if move=='fen':
            print(''.join(b.sq)+' ' + ('w' if b.wtm else 'b')) ; continue
        if move=='resign':
            print(side,'resigns. Game over.') ; break
        if isinstance(move,Move):
            b.make(move)
            outcome=b.outcome()
            if outcome:
                print(b); print(outcome); break
        else:
            print('Illegal or malformed input. Type help for syntax.')
if __name__=='__main__':
    main()
```
