function elo(data) {
  // -----------------------------------------------------------
  // Validation
  // -----------------------------------------------------------
  if (!Array.isArray(data)) {
    throw new TypeError("Expected an array of player objects");
  }
  if (data.length < 2) {
    throw new RangeError("Need at least two players to run elo()");
  }
  if (!data.every(p => typeof p.Matches === "number" && !Number.isNaN(p.Matches))) {
    throw new TypeError("Every player object must contain a numeric 'Matches' property");
  }

  // -----------------------------------------------------------
  // Player1 : fewest Matches (single O(n) scan)
  // -----------------------------------------------------------
  const player1 = data.reduce((min, cur) =>
    cur.Matches < min.Matches ? cur : min, data[0]);

  // -----------------------------------------------------------
  // Player2 : random among the remaining players
  // -----------------------------------------------------------
  const remaining = data.filter(p => p !== player1);   // excludes Player1 only
  const randomIndex = Math.floor(Math.random() * remaining.length);
  const player2 = remaining[randomIndex];

  // Return without mutating original objects
  return { Player1: player1, Player2: player2 };
}

