/**
 * Compute the n-th Fibonacci number modulo p using fast doubling.
 * Time complexity: O(log n)
 * Memory: O(log n) recursion depth
 * Works with arbitrarily large n and p thanks to BigInt (ES2020+)
 * 
 * @param {bigint|number} n – index (non-negative integer)
 * @param {bigint|number} p – modulus (positive integer)
 * @returns {bigint} F(n) mod p
 */
function fibMod(n, p) {
  // Type & range checks
  if ((typeof n !== 'bigint' && typeof n !== 'number') || !Number.isInteger(Number(n)))
      throw new TypeError('n must be an integer');
  if ((typeof p !== 'bigint' && typeof p !== 'number') || !Number.isInteger(Number(p)))
      throw new TypeError('p must be an integer');
  n = BigInt(n);
  p = BigInt(p);
  if (n < 0n) throw new RangeError('n must be non-negative');
  if (p <= 0n) throw new RangeError('p must be positive');

  // fast-doubling recursion: returns [F(k), F(k+1)] mod p
  function fd(k) {
    if (k === 0n) return [0n, 1n];
    const [a, b] = fd(k >> 1n);        // a = F(k/2), b = F(k/2+1)
    const c = (a * ((2n * b - a + p) % p)) % p; // F(2m)
    const d = (a * a + b * b) % p;              // F(2m+1)
    return (k & 1n) === 0n ? [c, d] : [d, (c + d) % p];
  }

  return fd(n)[0];
}

// ----- quick self-tests -----
console.assert(fibMod(0, 17) === 0n);
console.assert(fibMod(1, 31) === 1n);
console.assert(fibMod(10, 97) === 55n);        // F10 = 55
console.assert(fibMod(50, 1) === 0n);          // anything mod 1 is 0
console.assert(fibMod(1000000000000000000n, 1000000007n) === 284648363n);

