    var c = Vector2i(floor(global_pos.x/chunk_size),floor(global_pos.z/chunk_size))
    var chunk:Chunk = _chunks.get(c)
    if chunk==null:
        return
    var local = global_pos-Vector3i(c.x*chunk_size,0,c.y*chunk_size)
    chunk.blocks[_to_index(local)] = id
    chunk.dirty = true

func remove_block(global_pos:Vector3i):
    add_block(global_pos,0)

# ================ Internals ===================
func _init_noise():
    _noise = OpenSimplexNoise.new()
    _noise.seed = seed
    _noise.octaves = 4
    _noise.period = 64
    _noise.persistence = 0.5

func _update_visible_chunks(force:=false):
    if _player==null: return
    var pc = Vector2i(round(_player.global_position.x/chunk_size),round(_player.global_position.z/chunk_size))
    for x in range(pc.x-view_distance_in_chunks,pc.x+view_distance_in_chunks+1):
        for z in range(pc.y-view_distance_in_chunks,pc.y+view_distance_in_chunks+1):
            var key = Vector2i(x,z)
            if !_chunks.has(key): _create_chunk(key)
    _rebuild_dirty_chunks(force)

func _create_chunk(coord:Vector2i):
    var chunk = Chunk.new()
    chunk.pos = coord
    chunk.blocks = PackedByteArray(); chunk.blocks.resize(chunk_size*chunk_height*chunk_size)
    _generate_chunk_blocks(chunk)
    chunk.mesh_instance = MeshInstance3D.new()
    chunk.mesh_instance.mesh = ArrayMesh.new()
    chunk.mesh_instance.material_override = terrain_material
    chunk.mesh_instance.transform.origin = Vector3(coord.x*chunk_size*block_scale,0,coord.y*chunk_size*block_scale)
    add_child(chunk.mesh_instance)
    _chunks[coord] = chunk

func _generate_chunk_blocks(chunk:Chunk):
    for x in range(chunk_size):
        for z in range(chunk_size):
            var wx = chunk.pos.x*chunk_size+x
            var wz = chunk.pos.y*chunk_size+z
            var h = int((_noise.get_noise_2d(wx,wz)*0.5+0.5)*50)+40
            h = clamp(h,1,chunk_height-1)
            for y in range(h):
                chunk.blocks[_to_index(Vector3i(x,y,z))] = 1 # grass/dirt

func _rebuild_dirty_chunks(force:=false):
    for chunk in _chunks.values():
        if force or chunk.dirty:
            _build_mesh(chunk)
            chunk.dirty = false

# ===== Meshing =====
const _DIRS = [Vector3i(0,1,0),Vector3i(0,-1,0),Vector3i(1,0,0),Vector3i(-1,0,0),Vector3i(0,0,1),Vector3i(0,0,-1)]
const _FACE_VERTS = [
    [Vector3(0,1,0),Vector3(1,1,0),Vector3(1,1,1),Vector3(0,1,1)],
    [Vector3(0,0,1),Vector3(1,0,1),Vector3(1,0,0),Vector3(0,0,0)],
    [Vector3(1,0,0),Vector3(1,0,1),Vector3(1,1,1),Vector3(1,1,0)],
    [Vector3(0,0,1),Vector3(0,0,0),Vector3(0,1,0),Vector3(0,1,1)],
    [Vector3(0,0,1),Vector3(1,0,1),Vector3(1,1,1),Vector3(0,1,1)],
    [Vector3(1,0,0),Vector3(0,0,0),Vector3(0,1,0),Vector3(1,1,0)]
]

func _build_mesh(chunk:Chunk):
    var st = SurfaceTool.new(); st.begin(Mesh.PRIMITIVE_TRIANGLES)
    for x in range(chunk_size):
        for y in range(chunk_height):
            for z in range(chunk_size):
                var idx = _to_index(Vector3i(x,y,z))
                if chunk.blocks[idx]==0: continue
                for d in 6:
                    var n = Vector3i(x,y,z)+_DIRS[d]
                    if _is_air(chunk,n): _push_face(st,Vector3i(x,y,z),d)
    chunk.mesh_instance.mesh = st.commit(chunk.mesh_instance.mesh)

func _push_face(st:SurfaceTool,pos:Vector3i,d:int):
    var base = (pos*block_scale).to_vector3()
    for i in 4:
        st.add_vertex(base + _FACE_VERTS[d][i]*block_scale)
    var off = st.get_vertex_count()-4
    st.add_index(off); st.add_index(off+1); st.add_index(off+2)
    st.add_index(off); st.add_index(off+2); st.add_index(off+3)

# ===== Utility =====
func _to_index(p:Vector3i)->int:
    return p.y*chunk_size*chunk_size + p.z*chunk_size + p.x

func _is_air(chunk:Chunk,l:Vector3i)->bool:
    if l.x<0 or l.z<0 or l.y<0 or l.x>=chunk_size or l.z>=chunk_size or l.y>=chunk_height: return true
    return chunk.blocks[_to_index(l)]==0

# ===== Simple Interaction =====
func _unhandled_input(event):
    if event is InputEventMouseButton and event.button_index==MOUSE_BUTTON_LEFT and event.pressed:
        var s = get_world_3d().direct_space_state
        var ray_from = _player.global_transform.origin
        var ray_to   = ray_from + _player.transform.basis.z*-5.0
        var r = s.intersect_ray(ray_from,ray_to)
        if r: remove_block(r.position.floor())

//---------------- Example of a strong answer ----------------
// Generates a sequence of 32-bit values where EXACTLY 5 bits change
// with respect to the previous value.

class transition_gen;
   // "curr" is randomized each cycle; "prev" is held from last cycle.
   rand logic [31:0] curr;
   logic        [31:0] prev;

   // ---------- Constraint block ----------
   constraint trans_c {
      // Hamming distance between prev and curr must be 5
      $countones(curr ^ prev) == 5;

      // (Optional) Avoid trivial repeats, i.e. no all-zero toggles
      // curr != prev; // redundant because countones==5 already guarantees it

      // Ensure the solver treats PREV as known before solving CURR
      solve prev before curr;
   }

   // After each successful randomize, update prev for next cycle.
   function void post_randomize();
      prev = curr;
   endfunction
endclass

// ------------------ Testbench snippet ------------------
module tb;
   transition_gen gen = new();
   int i;
   initial begin
      // Initialise previous value explicitly; could be any legal 32-bit value
      gen.prev = 32'hDEAD_BEEF;
      for (i = 0; i < 10; i++) begin
         if (!gen.randomize()) $error("Unsatisfied constraint");
         $display("Iteration %0d: curr = %h  (prev = %h)  ones(prev^curr) = %0d", 
                  i, gen.curr, gen.prev, $countones(gen.curr ^ gen.prev));
      end
   end
endmodule

// ---- Notes ----
// 1. $countones(<expr>) is IEEE-1800-2017 compliant; older tools may use $onehot_count or lack support—
//    fall back to explicit bit loop if necessary.
// 2. If the randomization ever fails (e.g., prev has X/Z), the testbench prints an error.
// 3. Because 5 << 32, the constraint is always solvable; no additional coverage constraints required.
// 4. Alternative portable solution without $countones():
//      int unsigned diff_cnt;
//      constraint diff_loop {
//         diff_cnt == 5;
//         foreach (curr[i]) diff_cnt -= (curr[i] ^ prev[i]);
//         diff_cnt == 0;
//      }
//    but $countones is far more compact and clearer.

