(*---------------------------------------------------------------------*)
(*  dot_product.ml – OCaml + OpenGL 4.3 compute-shader dot product      *)
(*  Build (Linux + opam):                                              *)
(*  opam install glfw.3 gl bigarray                                    *)
(*  ocamlfind ocamlopt -linkpkg -package glfw3,gl,bigarray dot_product.ml -o dot_product *)
(*---------------------------------------------------------------------*)

open Bigarray
open Gl           (* raw OpenGL bindings from the "gl" opam package *)
open Glfw         (* window/context bootstrap *)

(* --------------------------- Helpers -------------------------------- *)
let check_shader status name info_fun =
  if status = Gl._FALSE then (
    Printf.eprintf "ERROR: %s failed\n%s\n" name (info_fun ());
    exit 1)

let compile_compute_shader src =
  let sid = Gl.createShader Gl.COMPUTE_SHADER in
  Gl.shaderSource sid src;
  Gl.compileShader sid;
  check_shader (Gl.getShaderiv sid Gl.COMPILE_STATUS)
               "Compute shader compilation" (fun () -> Gl.getShaderInfoLog sid);
  sid

let link_program sid =
  let pid = Gl.createProgram () in
  Gl.attachShader pid sid;
  Gl.linkProgram pid;
  check_shader (Gl.getProgramiv pid Gl.LINK_STATUS)
               "Program linking" (fun () -> Gl.getProgramInfoLog pid);
  pid

(* ------------------------- GLSL Shader ------------------------------ *)
let compute_shader_src = {|#version 430
layout(local_size_x = 256) in;

layout(std430, binding = 0) readonly buffer VecA { float a[]; };
layout(std430, binding = 1) readonly buffer VecB { float b[]; };
layout(std430, binding = 2) writeonly  buffer Res  { float result[]; };

shared float cache[256];

void main() {
  uint gid = gl_GlobalInvocationID.x;
  cache[gl_LocalInvocationID.x] = a[gid] * b[gid];
  barrier();
  for (uint stride = 128u; stride > 0u; stride >>= 1u) {
    if (gl_LocalInvocationID.x < stride)
      cache[gl_LocalInvocationID.x] += cache[gl_LocalInvocationID.x + stride];
    barrier();
  }
  if (gl_LocalInvocationID.x == 0u)
    atomicAdd(result[0], cache[0]);
}|}

(* --------------------------- Main ----------------------------------- *)
let () =
  (* 1. Init GLFW + OpenGL 4.3 context *)
  if not (Glfw.init ()) then failwith "Cannot init GLFW";
  Glfw.windowHint Glfw.CONTEXT_VERSION_MAJOR 4;
  Glfw.windowHint Glfw.CONTEXT_VERSION_MINOR 3;
  Glfw.windowHint Glfw.OPENGL_PROFILE Glfw.OPENGL_CORE_PROFILE;
  let win = Option.get (Glfw.createWindow ~width:1 ~height:1 ~title:"headless" ()) in
  Glfw.makeContextCurrent (Some win);

  (* 2. Prepare data *)
  let n = 1024 in
  let vec_a = Array.init n (fun i -> float_of_int (i + 1)) in
  let vec_b = Array.make n 1.0 in        (* dot = n*(n+1)/2 *)
  let expected = (float_of_int n *. float_of_int (n + 1)) /. 2.0 in

  let ba_of_array arr =
    let ba = Array1.create float32 c_layout n in
    Array.iteri (Array1.set ba) arr; ba in
  let ba_a = ba_of_array vec_a and ba_b = ba_of_array vec_b in

  (* 3. Create SSBOs *)
  let make_ssbo binding ba =
    let buf = Gl.genBuffer () in
    Gl.bindBuffer Gl.SHADER_STORAGE_BUFFER buf;
    let size = Array1.dim ba * 4 in  (* float32 *)
    Gl.bufferData Gl.SHADER_STORAGE_BUFFER size
      (Some (Bigarray.array1_of_genarray (Obj.magic ba))) Gl.STATIC_DRAW;
    Gl.bindBufferBase Gl.SHADER_STORAGE_BUFFER binding buf; buf in
  ignore (make_ssbo 0 ba_a);
  ignore (make_ssbo 1 ba_b);
  (* result buffer: one float initialised to 0 *)
  let res_buf = Gl.genBuffer () in
  Gl.bindBuffer Gl.SHADER_STORAGE_BUFFER res_buf;
  let zero = Array1.create float32 c_layout 1 in Array1.set zero 0 0.0;
  Gl.bufferData Gl.SHADER_STORAGE_BUFFER 4
    (Some (Bigarray.array1_of_genarray (Obj.magic zero))) Gl.DYNAMIC_READ;
  Gl.bindBufferBase Gl.SHADER_STORAGE_BUFFER 2 res_buf;

  (* 4. Compile & link shader *)
  let prog = link_program (compile_compute_shader compute_shader_src) in

  (* 5. Dispatch compute *)
  Gl.useProgram prog;
  let groups = (n + 255) / 256 in
  Gl.dispatchCompute groups 1 1;
  Gl.memoryBarrier Gl.SHADER_STORAGE_BARRIER_BIT;

  (* 6. Read back result *)
  Gl.bindBuffer Gl.SHADER_STORAGE_BUFFER res_buf;
  let ptr = Gl.mapBufferRange Gl.SHADER_STORAGE_BUFFER 0 4 Gl.MAP_READ_BIT in
  let res = Bigarray.(Array1.get (array1_of_genarray (Obj.magic ptr)) 0) in
  Printf.printf "GPU dot product = %f (expected %f)\n" res expected;
  Gl.unmapBuffer Gl.SHADER_STORAGE_BUFFER;

  (* 7. Cleanup *)
  Gl.deleteProgram prog;
  Gl.deleteShader (Gl.getAttachedShaders prog |> List.hd);
  Glfw.destroyWindow win;
  Glfw.terminate ()

// =========================
// Vertex shader (fullscreen quad)
// =========================
#version 330 core
layout(location = 0) in vec2 aPosition;      // –1..1 full-screen quad
out vec2 vUV;                                // Normalised 0..1 fragment coords
void main()
{
    vUV = (aPosition + 1.0) * 0.5;           // map –1..1 → 0..1
    gl_Position = vec4(aPosition, 0.0, 1.0); // pass straight through
}

// =========================
// Fragment shader (old-school ray-caster)
// =========================
#version 330 core
in  vec2 vUV;
out vec4 fragColor;

// ---------- Uniform inputs ----------
uniform sampler2D uMap;        // R channel = tile id (0 = empty)
uniform sampler2D uAtlas;      // Horizontal strip of 64×64 wall textures

uniform vec2  uPlayerPos;      // world units (float for sub-tile)
uniform vec2  uPlayerDir;      // normalised direction
uniform vec2  uCameraPlane;    // 90° plane (perp to dir) that scales FOV

uniform float uScreenWidth;    // pixels
uniform float uScreenHeight;   // pixels
const  int   MAX_STEPS = 64;   // hard stop to keep GPU happy

// Utility: fetch map value with bounds test
int mapValue(ivec2 m)
{
    // texelFetch uses integer coords → perfect for grid look-up
    if (m.x < 0 || m.y < 0 || m.x >= textureSize(uMap, 0).x || m.y >= textureSize(uMap, 0).y)
        return 1;                        // treat outside map as solid wall
    return int(texture(uMap, (vec2(m) + 0.5) / vec2(textureSize(uMap,0))).r * 255.0 + 0.5);
}

void main()
{
    //------------------------------------
    // 1) Compute ray direction for this column
    //------------------------------------
    float cameraX = 2.0 * gl_FragCoord.x / uScreenWidth - 1.0;  // –1 .. 1
    vec2  rayDir  = uPlayerDir + uCameraPlane * cameraX;

    //------------------------------------
    // 2) Prepare DDA variables
    //------------------------------------
    ivec2 mapPos  = ivec2(floor(uPlayerPos));
    vec2  delta   = abs(vec2(1.0) / rayDir);   // length from one x-side to next x-side, etc.

    ivec2 step;
    vec2  sideDist;
    if (rayDir.x < 0.0) { step.x = -1; sideDist.x = (uPlayerPos.x - float(mapPos.x)) * delta.x; }
    else                { step.x =  1; sideDist.x = (float(mapPos.x + 1) - uPlayerPos.x) * delta.x; }
    if (rayDir.y < 0.0) { step.y = -1; sideDist.y = (uPlayerPos.y - float(mapPos.y)) * delta.y; }
    else                { step.y =  1; sideDist.y = (float(mapPos.y + 1) - uPlayerPos.y) * delta.y; }

    //------------------------------------
    // 3) Walk the grid (DDA)
    //------------------------------------
    int side = 0;     // 0 = x-side, 1 = y-side
    int tile = 0;
    for (int i = 0; i < MAX_STEPS; ++i)
    {
        if (sideDist.x < sideDist.y) {
            sideDist.x += delta.x; mapPos.x += step.x; side = 0; }
        else                       {
            sideDist.y += delta.y; mapPos.y += step.y; side = 1; }

        tile = mapValue(mapPos);
        if (tile != 0) break;                       // hit non-empty cell
    }

    //------------------------------------
    // 4) No wall: render sky/floor gradient
    //------------------------------------
    if (tile == 0) {
        float t = vUV.y;
        fragColor = mix(vec4(0.5,0.7,1.0,1.0), vec4(0.2,0.2,0.2,1.0), t);
        return;
    }

    //------------------------------------
    // 5) Distance to wall (perpendicular to screen to remove fisheye)
    //------------------------------------
    float perpDist = (side == 0)
        ? (float(mapPos.x) - uPlayerPos.x + (1.0 - float(step.x)) * 0.5) / rayDir.x
        : (float(mapPos.y) - uPlayerPos.y + (1.0 - float(step.y)) * 0.5) / rayDir.y;

    //------------------------------------
    // 6) Compute size of slice that will be drawn for this column
    //------------------------------------
    float lineH   = uScreenHeight / perpDist; // classic formula
    float drawBeg = -lineH * 0.5 + uScreenHeight * 0.5;
    float drawEnd =  lineH * 0.5 + uScreenHeight * 0.5;

    //------------------------------------
    // 7) Pixels above / below slice → sky / floor
    //------------------------------------
    if (gl_FragCoord.y < drawBeg) {
        fragColor = vec4(0.5,0.7,1.0,1.0);   // sky blue
        return;
    }
    if (gl_FragCoord.y > drawEnd) {
        fragColor = vec4(0.25,0.25,0.25,1.0); // dark floor
        return;
    }

    //------------------------------------
    // 8) Sample wall texture
    //------------------------------------
    float hitPoint = (side == 0)
        ? (uPlayerPos.y + perpDist * rayDir.y)
        : (uPlayerPos.x + perpDist * rayDir.x);
    float texX = fract(hitPoint);                    // column on wall 0..1
    // Flip horizontal texture when hitting from right/upper side to match Wolf3D look
    if ((side == 0 && rayDir.x > 0.0) || (side == 1 && rayDir.y < 0.0))
        texX = 1.0 - texX;

    float texY = (gl_FragCoord.y - drawBeg) / lineH; // vertical coordinate 0..1

    // Atlas layout: textures sit side-by-side, id 1..N; each 64px wide
    vec2 atlasSize = vec2(textureSize(uAtlas,0));
    float tilesInAtlas = atlasSize.x / 64.0;
    vec2 texCoord = vec2((texX + float(tile - 1)) / tilesInAtlas, texY);
    vec4 color = texture(uAtlas, texCoord);

    // Darken y-side for depth cue like original games
    if (side == 1) color.rgb *= 0.7;

    fragColor = color;
}

