import java.util.*;
import java.util.stream.Collectors;

public class StreamHelpers {
    /**
     * Returns the single element contained in {@code list},
     * {@code null} if the list is empty, and throws an
     * {@link IllegalStateException} if the list contains more than one element.
     * <p>
     * The implementation relies exclusively on the Java Stream API and stops
     * processing after the second element for efficiency.
     *
     * @param list the list to inspect (must not be {@code null})
     * @param <T>  the element type
     * @return the sole element or {@code null}
     * @throws NullPointerException  if {@code list} is {@code null}
     * @throws IllegalStateException if {@code list} contains more than one element
     */
    public static <T> T getSingleOrNull(List<T> list) {
        Objects.requireNonNull(list, "Input list must not be null");

        return list.stream()
                // we never need to look past the 2nd element
                .limit(2)
                .collect(Collectors.collectingAndThen(
                        Collectors.toList(),
                        collected -> {
                            if (collected.size() > 1) {
                                throw new IllegalStateException(
                                        "Expected at most one element but found " + collected.size());
                            }
                            return collected.isEmpty() ? null : collected.get(0);
                        }));
    }

    // --- quick demonstration ---
    public static void main(String[] args) {
        System.out.println(getSingleOrNull(Collections.emptyList()));          // prints: null
        System.out.println(getSingleOrNull(Collections.singletonList("only"))); // prints: only
        System.out.println(getSingleOrNull(Arrays.asList("a", "b")));          // throws IllegalStateException
    }
}

