## kalman_sequence.m
##  GNU Octave implementation of a discrete Kalman filter applied to a sequence
##  of observations.
##
##  [x_hat, P_hat, loglik] = kalman_sequence(z, A, H, Q, R, x0, P0)
##
##  INPUTS
##    z   : (m x N) matrix of observations, each column z(:,k)
##    A   : (n x n) state-transition matrix
##    H   : (m x n) observation matrix
##    Q   : (n x n) process-noise covariance   (>=0 definite)
##    R   : (m x m) measurement-noise covariance (>=0 definite)
##    x0  : (n x 1) initial state estimate
##    P0  : (n x n) initial error covariance   (>=0 definite)
##
##  OUTPUTS
##    x_hat : (n x N) posterior state estimates for k = 1..N
##    P_hat : (n x n x N) posterior covariance for each k
##    loglik: scalar log-likelihood of the measurement sequence (optional)
##
##  The function follows the standard predict–update cycle:
##    1) Predict:  x_prior = A * x_hat(:,k-1)
##                 P_prior = A * P_hat(:,:,k-1) * A' + Q
##    2) Update:   S = H * P_prior * H' + R
##                 K = P_prior * H' / S        (numerically stable using backslash)
##                 innov = z(:,k)  H * x_prior
##                 x_hat(:,k) = x_prior + K * innov
##                 P_hat(:,:,k) = (I  K*H) * P_prior
##
function [x_hat, P_hat, loglik] = kalman_sequence(z, A, H, Q, R, x0, P0)
  if (nargin < 8)
    error("Usage: [x_hat, P_hat] = kalman_sequence(z, A, H, Q, R, x0, P0)");
  end

  [m, N] = size(z);
  n = length(x0);
  I = eye(n);

  x_hat = zeros(n, N);
  P_hat = zeros(n, n, N);
  loglik = 0;

  % Initial values
  x_prev = x0;
  P_prev = P0;

  for k = 1:N
    % ---------- Predict ----------
    x_pred = A * x_prev;
    P_pred = A * P_prev * A' + Q;

    % ---------- Update ----------
    S = H * P_pred * H' + R;
    % Solve P_pred*H'/S instead of explicit inverse
    K = (P_pred * H') / S;  % Same as K = P_pred*H'*inv(S) but numerically stable
    innov = z(:, k) - H * x_pred;
    x_curr = x_pred + K * innov;
    P_curr = (I - K * H) * P_pred;

    % Store results
    x_hat(:, k) = x_curr;
    P_hat(:, :, k) = P_curr;

    % Update log-likelihood (optional)
    loglik = loglik - 0.5 * (m * log(2*pi) + log(det(S)) + innov' / S * innov);

    % Prepare for next step
    x_prev = x_curr;
    P_prev = P_curr;
  end
endfunction

### Minimal reproducible example
% Example: 1-D constant-velocity model
N  = 50;              % number of steps
A  = [1 1; 0 1];      % state transition (x, v)
H  = [1 0];           % we observe position only
Q  = 0.01 * eye(2);   % small process noise
R  = 0.1;             % measurement noise variance

% Simulate ground truth and noisy measurement
x_true = zeros(2, N);
z      = zeros(1, N);
x_true(:,1) = [0; 1];
for k = 2:N
  x_true(:,k) = A * x_true(:,k-1) + mvnrnd([0;0], Q)';
end
z = x_true(1,:) + sqrt(R) * randn(1, N);

% Run the filter
[x_hat, P_hat] = kalman_sequence(z, A, H, Q, R, [0;0], eye(2));

% Plot results
figure;
plot(1:N, x_true(1,:), 'g-', 1:N, z, 'rx', 1:N, x_hat(1,:), 'b-');
legend('True position', 'Measured', 'Estimated');
xlabel('Time step'); ylabel('Position'); grid on;

printf('Final position error: %.4f\n', norm(x_hat(1,end) - x_true(1,end)) );

