// app/Favorites/FavoritesManager.php
<?php

namespace App\Favorites;

use App\Models\Favorite;
use App\Models\User;
use Illuminate\Contracts\Session\Session;
use Illuminate\Support\Str;

class FavoritesManager
{
    private ?User $user;
    private Session $session;

    /** Session key for guest favorites */
    private const SESSION_KEY = 'favorites';

    public function __construct(Session $session, ?User $user = null)
    {
        $this->session = $session;
        $this->user    = $user;
    }

    /* ---------------- Public API ---------------- */
    public function all(): array
    {
        return $this->isGuest()
            ? $this->session->get(self::SESSION_KEY, [])
            : Favorite::where('user_id', $this->user->id)->pluck('name')->all();
    }

    public function add(string $name): bool
    {
        $name = $this->normalize($name);
        if ($name === '' || $this->exists($name)) {
            return false;
        }
        return $this->isGuest() ? $this->addToSession($name) : $this->addToDatabase($name);
    }

    public function remove(string $name): bool
    {
        $name = $this->normalize($name);
        if (! $this->exists($name)) {
            return false;
        }
        return $this->isGuest() ? $this->removeFromSession($name) : $this->removeFromDatabase($name);
    }

    /** Merge guest favorites once user logs in */
    public function migrateSessionFavoritesToUser(): void
    {
        if ($this->isGuest()) {
            return;
        }
        foreach ($this->session->pull(self::SESSION_KEY, []) as $fav) {
            $this->addToDatabase($fav); // silently ignore duplicates
        }
    }

    /* ------------- Helpers ------------- */
    private function exists(string $name): bool
    {
        return in_array($name, $this->all(), true);
    }

    private function addToSession(string $name): bool
    {
        $current = $this->session->get(self::SESSION_KEY, []);
        $current[] = $name;
        $this->session->put(self::SESSION_KEY, $current);
        return true;
    }

    private function removeFromSession(string $name): bool
    {
        $current = array_values(array_filter(
            $this->session->get(self::SESSION_KEY, []),
            fn ($item) => $item !== $name
        ));
        $this->session->put(self::SESSION_KEY, $current);
        return true;
    }

    private function addToDatabase(string $name): bool
    {
        Favorite::firstOrCreate([
            'user_id' => $this->user->id,
            'name'    => $name,
        ]);
        return true;
    }

    private function removeFromDatabase(string $name): bool
    {
        Favorite::where('user_id', $this->user->id)->where('name', $name)->delete();
        return true;
    }

    private function normalize(string $name): string
    {
        return Str::of($name)->trim()->lower()->__toString();
    }

    private function isGuest(): bool
    {
        return is_null($this->user);
    }
}

