class FavoritesController extends Controller
{
    private FavoritesManager $favorites;

    public function __construct(FavoritesManager $favorites)
    {
        $this->favorites = $favorites;
        if (Auth::check()) {
            $this->favorites->migrateSessionFavoritesToUser();
        }
    }

    /** GET /api/favorites */
    public function index(): Response
    {
        return response()->json(['data' => $this->favorites->all()]);
    }

    /** POST /api/favorites  { name: "Acme" } */
    public function store(Request $request): Response
    {
        $validated = $request->validate([
            'name' => 'required|string|max:255',
        ]);

        $added = $this->favorites->add($validated['name']);

        return response()->json([
            'added'   => $added,
            'current' => $this->favorites->all(),
        ], $added ? 201 : 200);
    }

    /** DELETE /api/favorites/{name} */
    public function destroy(string $name): Response
    {
        $removed = $this->favorites->remove($name);

        return response()->json([
            'removed' => $removed,
            'current' => $this->favorites->all(),
        ], $removed ? 200 : 404);
    }
}

