Below is a concise but complete pattern that: (a) provides a DEFAULT mock for the `axios` HTTP client in `setupFilesAfterEnv`, and (b) overrides that mock with a different implementation for one specific test file.

──────────────── jest.config.js ────────────────
module.exports = {
  // …other config
  setupFilesAfterEnv: ["<rootDir>/jest.setup.js"],
};

──────────────── jest.setup.js (runs once *per* test file *after* the test framework is installed) ────────────────
//   1️⃣ Provide a GLOBAL/DEFAULT mock of axios
//      that will be used in *all* tests *unless* a test overrides it.
//   2️⃣ We put the mock here because jest.setup.js is executed *before*
//      any test file code, so it acts as a safety-net default.
//   3️⃣ We keep the factory in a separate function so individual tests can
//      re-use it when they want the same behaviour.

function defaultAxiosFactory() {
  return {
    get:  jest.fn(() => Promise.resolve({data: {global: true}})),
    post: jest.fn(() => Promise.resolve({data: {saved: true}})),
    // …other methods you need
  };
}

jest.mock("axios", () => defaultAxiosFactory());

// 👉 Export the factory so that tests can re-use or extend it if they like.
module.exports.defaultAxiosFactory = defaultAxiosFactory;

──────────────── some.spec.js (keeps default mock) ────────────────
import axios from "axios";   // ← receives the default mock defined above
import {myFunction} from "./myFunction"; // code that internally calls axios.get

test("returns global mock data", async () => {
  const result = await myFunction();
  expect(result).toEqual({global: true});
  expect(axios.get).toHaveBeenCalledWith("/endpoint");
});

──────────────── override.spec.js (needs a *different* mock) ────────────────
/**
 * The global mock defined in jest.setup.js runs BEFORE the hoisted mocks in this
 * file, so to override it we use `jest.doMock` *synchronously* before we
 * import the module under test. We must reset modules first to clear the cache.
 */

jest.resetModules(); // 1️⃣ wipe previous module cache so our new mock wins

jest.doMock("axios", () => ({               // 2️⃣ provide alternate behaviour
  get: jest.fn(() => Promise.resolve({data: {custom: true}})),
  post: jest.fn(() => Promise.reject(new Error("fail"))),
}));

// Now we can import the module(s) that use axios; they will receive *this* mock.
const {myFunction} = require("./myFunction");
const axios = require("axios");

test("uses custom mock in this file only", async () => {
  const result = await myFunction();
  expect(result).toEqual({custom: true});  // ← custom data
  expect(axios.get).toHaveBeenCalled();
});

──────────────── common pitfalls & notes ────────────────
• Don’t put `jest.mock("axios")` at the *top* of the test file *without* a factory—if you do, Jest hoists it and then the *global* mock in `jest.setup.js` will override it again. Use `doMock` (or `setMock` before `require`ing) combined with `resetModules` so that your local definition is the last one applied.
• Keep factories named so tests can re-use them and stay DRY.
• If you need the *real* module in one test, call `jest.unmock("axios")` after `resetModules()` and before the `require` call, or inside a `jest.isolateModules()` block.
• Always call `jest.resetModules()` when you change mocks at runtime to avoid leakage across tests.

With this pattern you can:
  – Provide a default mock that simplifies 90% of your tests.
  – Override or unmock per file when behaviour differs.
  – Keep mocks isolated and predictable across the suite.

