pragma solidity 0.8.18;

/*
 * @author not-so-secure-dev
 * @title PasswordStore
 * @notice This contract allows you to store a private password that others won't be able to see. 
 * You can update your password at any time.
 */
contract PasswordStore {
    error PasswordStore__NotOwner();

    address private s_owner;
    string private s_password;

    event SetNetPassword();

    constructor() {
        s_owner = msg.sender;
    }

    /*
     * @notice This function allows only the owner to set a new password.
     * @param newPassword The new password to set.
     */
    function setPassword(string memory newPassword) external {
        s_password = newPassword;
        emit SetNetPassword();
    }

    /*
     * @notice This allows only the owner to retrieve the password.
     * @param newPassword The new password to set.
     */
    function getPassword() external view returns (string memory) {
        if (msg.sender != s_owner) {
            revert PasswordStore__NotOwner();
        }
        return s_password;
    }
}
Detect the vulnearbility in this smart contract

excellent_response:
The contract contains a CRITICAL missing-access-control vulnerability in the `setPassword` function.

1️⃣ What’s wrong
────────────────
```solidity
function setPassword(string memory newPassword) external { // no owner check here
    s_password = newPassword;
    emit SetNetPassword();
}
```
Because there is **no `require(msg.sender == s_owner)` or `onlyOwner` modifier**, ANY address can call this and overwrite `s_password`. The getter is protected, so the owner will later read whatever value the attacker stored, assuming it is legitimate.

2️⃣ Impact / how to exploit
──────────────────────────
• Attacker (e.g., address 0xBEEF…) sends one transaction calling `setPassword("hacked")`.
• The string stored at storage slot 1 is now “hacked”.  The legitimate owner is locked out of the correct value – a denial-of-service and integrity failure.
• Attacker can repeatedly change it or demand a ransom to reset it.  Severity: **High**.
• No ETH is at risk; effect is on data integrity, not funds.

3️⃣ Privacy misconception
────────────────────────
Even if only the owner can call `getPassword`, the password is still **public**: anyone can run `eth_getStorageAt(<contract>, 0x1)` or inspect a block explorer to read it. The `private` keyword hides data only from other contracts at compile time.

4️⃣ Recommended fix
──────────────────
```solidity
modifier onlyOwner() {
    if (msg.sender != s_owner) revert PasswordStore__NotOwner();
    _;
}

function setPassword(string memory newPassword) external onlyOwner {
    s_password = newPassword;
    emit SetNetPassword();
}
```
