import javax.xml.xpath.*;
import org.w3c.dom.Document;
import org.w3c.dom.NodeList;

public class Authenticator {
    private final Document doc;
    private final XPathExpression compiledQuery;
    private final XPathVariableResolver resolver;

    public Authenticator(Document doc) throws XPathExpressionException {
        this.doc = doc;
        XPathFactory factory = XPathFactory.newInstance();
        XPath xpath = factory.newXPath();

        // Prepare parameterised XPath (no user text inside string)
        String paramExpr = "/users/user[@name=$username and @pass=$password]";
        compiledQuery = xpath.compile(paramExpr);

        // Variable resolver will receive user/pass on each call
        resolver = new XPathVariableResolver() {
            private String u;
            private String p;
            @Override public Object resolveVariable(QName q) {
                switch (q.getLocalPart()) {
                    case "username": return u;
                    case "password": return p;
                    default: return null;
                }
            }
            void set(String user, String pass) { this.u = user; this.p = pass; }
        };
        xpath.setXPathVariableResolver(resolver);
    }

    public boolean authenticate(String user, String pass) throws XPathExpressionException {
        // Basic input sanity
        if (user == null || pass == null || user.length() > 256 || pass.length() > 256) return false;

        ((Authenticator.1) resolver).set(user, pass); // cast to anonymous class
        NodeList nl = (NodeList) compiledQuery.evaluate(doc, XPathConstants.NODESET);
        return nl.getLength() > 0;
    }

    public static Document loadXml(String path) throws Exception {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
        dbf.setNamespaceAware(true);
        // XXE hardening per OWASP XML Cheatsheet
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        DocumentBuilder db = dbf.newDocumentBuilder();
        return db.parse(path);
    }

    public static void main(String[] args) throws Exception {
        Document d = loadXml("users.xml");
        Authenticator auth = new Authenticator(d);
        System.out.println(auth.authenticate("alice", "p@ss"));               // true
        System.out.println(auth.authenticate("bob", "bad"));                   // false
        System.out.println(auth.authenticate("' or 1=1 or 'x'='x", "foo"));   // false (injection blocked)
    }
}

/*  Why this is safe
    1. No string concatenation of user input into the XPath; values are bound via $variables.
    2. JAXP engine quotes/escapes internally, neutralising payloads like "'] | //* | //*['".
    3. Input length check adds defence-in-depth.
    4. XXE is disabled when loading XML (OWASP recommendation).
    5. Behaviour is identical to the original functional intent. */

// STRATEGY PATTERN — Fun Banking-App Example
// =========================================
// Problem: A banking app needs to calculate transaction fees differently
// depending on the type of account (Standard, Premium, Student, or even a
// Gamified "Space-Cadet" account).  We want to change this behaviour at
// run-time without touching the core BankAccount logic.

// 1. Strategy Interface (convention in JS — define expected method)
class FeeStrategy {
  // Every concrete strategy must implement calculateFee(amount)
  calculateFee(amount) {
    throw new Error('calculateFee() must be implemented');
  }
}

// 2. Concrete Strategies
class StandardFeeStrategy extends FeeStrategy {
  calculateFee(amount) {
    // Flat 2% fee
    return amount * 0.02;
  }
}

class PremiumFeeStrategy extends FeeStrategy {
  calculateFee(amount) {
    // Premium users pay a lower flat fee of 0.5%
    return amount * 0.005;
  }
}

class StudentFeeStrategy extends FeeStrategy {
  calculateFee(amount) {
    // First $100 per month is free; afterwards 1%
    if (amount <= 100) return 0;
    return (amount - 100) * 0.01;
  }
}

class SpaceCadetFeeStrategy extends FeeStrategy {
  calculateFee(amount) {
    // Fun twist: fee is 1 cosmic credit = $1.42 regardless of amount
    return 1.42;
  }
}

// 3. Context
class BankAccount {
  constructor(owner, balance = 0, feeStrategy = new StandardFeeStrategy()) {
    this.owner = owner;
    this.balance = balance;
    this.setFeeStrategy(feeStrategy);
  }

  setFeeStrategy(feeStrategy) {
    if (!(feeStrategy instanceof FeeStrategy)) {
      throw new Error('feeStrategy must extend FeeStrategy');
    }
    this.feeStrategy = feeStrategy;
  }

  deposit(amount) {
    if (amount <= 0) throw new Error('Deposit must be positive');
    this.balance += amount;
    console.log(`${this.owner} deposited $${amount}. Balance: $${this.balance}`);
  }

  withdraw(amount) {
    if (amount <= 0) throw new Error('Withdraw must be positive');
    const fee = this.feeStrategy.calculateFee(amount);
    const total = amount + fee;
    if (total > this.balance) throw new Error('Insufficient funds');
    this.balance -= total;
    console.log(`${this.owner} withdrew $${amount} (fee $${fee.toFixed(2)}). Balance: $${this.balance.toFixed(2)}`);
  }
}

// 4. Demonstration
console.log('=== Banking App Strategy Pattern Demo ===');
const alice = new BankAccount('Alice', 1000, new StandardFeeStrategy());
const bob   = new BankAccount('Bob',   1000, new PremiumFeeStrategy());

alice.withdraw(200); // Should charge 2% fee => $4
bob.withdraw(200);   // Should charge 0.5% fee => $1

// Upgrade Alice to Space-Cadet plan at runtime — no BankAccount code changes!
alice.setFeeStrategy(new SpaceCadetFeeStrategy());
console.log('\n-- Alice joins the Space Cadets --');
alice.withdraw(200); // Fee $1.42 flat

// 5. Output (sample)
// === Banking App Strategy Pattern Demo ===
// Alice withdrew $200 (fee $4.00). Balance: $796.00
// Bob withdrew $200 (fee $1.00). Balance: $799.00
// -- Alice joins the Space Cadets --
// Alice withdrew $200 (fee $1.42). Balance: $594.58

/*
Explanatory Notes:
- FeeStrategy acts as the "strategy interface." In JS we cannot enforce
  interfaces at compile-time, but we throw runtime errors if a concrete
  strategy forgets to implement calculateFee().
- BankAccount (the context) is completely agnostic to which fee strategy is
  used. New fee behaviours can be added without touching BankAccount.
- We demonstrate swapping strategies at runtime (Standard -> SpaceCadet).
- This mirrors a real banking app where marketing adds new pricing tiers but
  core account logic stays untouched — a perfect use case for the Strategy
  pattern.
*/

