const { Pool } = require('pg');
const app = express();
app.use(cors({ origin: 'http://localhost:3000' }));
app.use(helmet());
app.use(express.json());
const pool = new Pool({ connectionString: process.env.DATABASE_URL });
app.post('/todos', async (req, res) => {
  const { description } = req.body;
  const result = await pool.query('INSERT INTO todo(description) VALUES($1) RETURNING *',[description]);
  res.status(201).json(result.rows[0]);
});
app.get('/todos', async (_req, res) => {
  const result = await pool.query('SELECT * FROM todo ORDER BY todo_id');
  res.json(result.rows);
});
app.get('/todos/:id', async (req, res) => {
  const result = await pool.query('SELECT * FROM todo WHERE todo_id=$1',[req.params.id]);
  if(!result.rows.length) return res.status(404).json({error:'Not found'});
  res.json(result.rows[0]);
});
app.put('/todos/:id', async (req, res) => {
  const result = await pool.query('UPDATE todo SET description=$1 WHERE todo_id=$2 RETURNING *',[req.body.description,req.params.id]);
  if(!result.rowCount) return res.status(404).json({error:'Not found'});
  res.json(result.rows[0]);
});
app.delete('/todos/:id', async (req, res) => {
  const result = await pool.query('DELETE FROM todo WHERE todo_id=$1',[req.params.id]);
  if(!result.rowCount) return res.status(404).json({error:'Not found'});
  res.status(204).end();
});
app.listen(process.env.PORT||5000);

