/*  Excellent sample solution demonstrating clear structure, robust validation, clean output, and the classic Euclidean algorithm  */
import java.util.InputMismatchException;
import java.util.Scanner;

public class GCDCalculator {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = readPositiveInt(sc, "Enter the first positive integer: ");
        int b = readPositiveInt(sc, "Enter the second positive integer: ");
        int gcd = computeGCD(a, b);
        System.out.printf("The greatest common divisor of %d and %d is %d.%n", a, b, gcd);
        sc.close();
    }

    /**
     * Reads a single positive integer from the user, reprompting until the input is valid.
     */
    private static int readPositiveInt(Scanner sc, String prompt) {
        int num = -1;
        while (num <= 0) {
            System.out.print(prompt);
            try {
                num = sc.nextInt();
                if (num <= 0) {
                    System.out.println("Error: number must be positive. Please try again.");
                }
            } catch (InputMismatchException e) {
                System.out.println("Error: please enter a valid integer.");
                sc.next(); // clear invalid token
            }
        }
        return num;
    }

    /**
     * Computes GCD using the iterative Euclidean algorithm.
     */
    private static int computeGCD(int x, int y) {
        while (y != 0) {
            int temp = y;
            y = x % y;
            x = temp;
        }
        return Math.abs(x);
    }
}

