// Vanilla character-level RNN from scratch in plain TypeScript
// ============================================================
// 0) HOW TO RUN ----------------------------------------------
//    npm install -g ts-node
//    ts-node rnn.ts
//    (No other dependencies used.)
// 1) MATHEMATICAL BACKGROUND ---------------------------------
//    h_t = tanh(Wxh·x_t + Whh·h_{t-1} + b_h)
//    y_t = Why·h_t + b_y
//    p_t = softmax(y_t)                       (classification)
//    Loss  = −log p_t[target]
//    Gradients are accumulated through time and parameters are
//    updated with simple SGD and gradient clipping ±5.
//----------------------------------------------------------------

/* ----------  Utility Types & Functions  ---------- */

type Matrix = number[][]; // dense 2-D matrix

function zeros(r: number, c: number): Matrix {
  return Array.from({ length: r }, () => Array(c).fill(0));
}

function rand(r: number, c: number, scale = 0.08): Matrix {
  return Array.from({ length: r }, () =>
    Array.from({ length: c }, () => (Math.random() * 2 - 1) * scale)
  );
}

function dot(A: Matrix, B: Matrix): Matrix {
  const out = zeros(A.length, B[0].length);
  for (let i = 0; i < A.length; i++)
    for (let k = 0; k < B.length; k++)
      for (let j = 0; j < B[0].length; j++)
        out[i][j] += A[i][k] * B[k][j];
  return out;
}

function add(A: Matrix, B: Matrix): Matrix {
  return A.map((row, i) => row.map((v, j) => v + B[i][j]));
}

function tanh(M: Matrix): Matrix {
  return M.map(row => row.map(Math.tanh));
}

function tanhDeriv(M: Matrix): Matrix {
  return M.map(row => row.map(v => 1 - v * v));
}

function softmax(v: number[]): number[] {
  const max = Math.max(...v);
  const exps = v.map(x => Math.exp(x - max));
  const sum = exps.reduce((a, b) => a + b, 0);
  return exps.map(e => e / sum);
}

function oneHot(idx: number, size: number): number[] {
  const vec = Array(size).fill(0);
  vec[idx] = 1;
  return vec;
}

function transpose(M: Matrix): Matrix {
  const out = zeros(M[0].length, M.length);
  for (let i = 0; i < M.length; i++)
    for (let j = 0; j < M[0].length; j++) out[j][i] = M[i][j];
  return out;
}

/* --------------- RNN Model Class --------------- */

class VanillaRNN {
  inputSize: number;
  hiddenSize: number;
  outputSize: number;
  learningRate: number;
  Wxh: Matrix;
  Whh: Matrix;
  Why: Matrix;
  bh: Matrix;
  by: Matrix;

  constructor(input: number, hidden = 64, lr = 0.1) {
    this.inputSize = input;
    this.hiddenSize = hidden;
    this.outputSize = input; // next-char prediction
    this.learningRate = lr;

    this.Wxh = rand(hidden, input);
    this.Whh = rand(hidden, hidden);
    this.Why = rand(this.outputSize, hidden);
    this.bh = zeros(hidden, 1);
    this.by = zeros(this.outputSize, 1);
  }

  // -------- Forward pass for an entire sequence --------
  forward(seq: number[]) {
    const xs: Matrix[] = [];
    const hs: Matrix[] = [zeros(this.hiddenSize, 1)]; // h_{-1}
    const ps: number[][] = [];
    let loss = 0;

    for (let t = 0; t < seq.length - 1; t++) {
      const xCol = oneHot(seq[t], this.inputSize).map(v => [v]);
      xs.push(xCol);

      const hRaw = add(add(dot(this.Wxh, xCol), dot(this.Whh, hs[t])), this.bh);
      const h = tanh(hRaw);
      hs.push(h);

      const y = add(dot(this.Why, h), this.by);
      const p = softmax(y.map(r => r[0]));
      ps.push(p);
      loss += -Math.log(p[seq[t + 1]] + 1e-9);
    }
    return { xs, hs, ps, loss };
  }

  // -------- Back-propagation through time --------------
  backward(cache: ReturnType<this["forward"]>, targets: number[]) {
    const { xs, hs, ps } = cache;
    const dWxh = zeros(this.hiddenSize, this.inputSize);
    const dWhh = zeros(this.hiddenSize, this.hiddenSize);
    const dWhy = zeros(this.outputSize, this.hiddenSize);
    const dbh = zeros(this.hiddenSize, 1);
    const dby = zeros(this.outputSize, 1);

    let dhNext = zeros(this.hiddenSize, 1);

    for (let t = xs.length - 1; t >= 0; t--) {
      const dy = ps[t].slice();
      dy[targets[t + 1]] -= 1; // ∂L/∂y
      const dyCol = dy.map(v => [v]);

      // gradients for Why & by
      for (let i = 0; i < this.outputSize; i++)
        for (let j = 0; j < this.hiddenSize; j++)
          dWhy[i][j] += dyCol[i][0] * hs[t + 1][j][0];
      for (let i = 0; i < this.outputSize; i++) dby[i][0] += dyCol[i][0];

      // back into h
      let dh = dot(transpose(this.Why), dyCol);
      for (let i = 0; i < this.hiddenSize; i++) dh[i][0] += dhNext[i][0];
      const dhRaw = tanhDeriv(hs[t + 1]);
      for (let i = 0; i < this.hiddenSize; i++) dh[i][0] *= dhRaw[i][0];

      // parameter grads
      for (let i = 0; i < this.hiddenSize; i++)
        for (let j = 0; j < this.inputSize; j++)
          dWxh[i][j] += dh[i][0] * xs[t][j][0];
      for (let i = 0; i < this.hiddenSize; i++)
        for (let j = 0; j < this.hiddenSize; j++)
          dWhh[i][j] += dh[i][0] * hs[t][j][0];
      for (let i = 0; i < this.hiddenSize; i++) dbh[i][0] += dh[i][0];

      dhNext = dot(transpose(this.Whh), dh);
    }

    // -- SGD update with gradient clipping ±5 -------------
    const clip = (v: number) => Math.max(-5, Math.min(5, v));
    const apply = (param: Matrix, grad: Matrix) => {
      for (let i = 0; i < param.length; i++)
        for (let j = 0; j < param[0].length; j++)
          param[i][j] += -this.learningRate * clip(grad[i][j]);
    };

    apply(this.Wxh, dWxh);
    apply(this.Whh, dWhh);
    apply(this.Why, dWhy);
    apply(this.bh, dbh);
    apply(this.by, dby);
  }

  /* ------------ Text Sampling (inference) ------------- */
  sample(startIdx: number, charTable: string[], length = 30): string {
    let h = zeros(this.hiddenSize, 1);
    let idx = startIdx;
    let out = charTable[idx];
    for (let t = 0; t < length; t++) {
      const x = oneHot(idx, this.inputSize).map(v => [v]);
      h = tanh(add(add(dot(this.Wxh, x), dot(this.Whh, h)), this.bh));
      const y = add(dot(this.Why, h), this.by);
      const p = softmax(y.map(r => r[0]));
      idx = p.indexOf(Math.max(...p));
      out += charTable[idx];
    }
    return out;
  }
}

/* --------------- 2) Toy Training Example -------------- */

