// composables/useSession.ts
import { useQuery } from '@tanstack/vue-query'
import axios from 'axios'
import { useSessionStore } from '@/stores/session'

export function useSession () {
  const sessionStore = useSessionStore()

  // 1. Pure fetcher – no side-effects
  const fetchSession = async () => {
    const { data } = await axios.get('/get_session')
    return data            // returns JSON body only
  }

  const {
    data: session,
    isLoading,
    isError,
    error,
  } = useQuery(
    ['session'],           // stable cache key
    fetchSession,
    {
      // pick only required keys
      select: (raw) => ({ id: raw.id, email: raw.email, role: raw.role }),

      // sync Pinia on success (single side-effect location)
      onSuccess: (selected) => {
        if (selected.id !== sessionStore.id) {
          sessionStore.setSession(selected)
        }
      },

      staleTime: 60_000,          // 1-min fresh window
      retry: 1,
      refetchOnWindowFocus: false,
    },
  )

  return { session, isLoading, isError, error }
}

// stores/session.ts
import { defineStore } from 'pinia'

export const useSessionStore = defineStore('session', {
  state: () => ({
    id: null as number | null,
    email: '' as string,
    role: '' as string,
  }),
  actions: {
    setSession (payload: { id: number; email: string; role: string }) {
      this.$patch(payload)
    },
  },
})

// Example component usage
<script setup lang="ts">
import { useSession } from '@/composables/useSession'

const { session, isLoading, isError, error } = useSession()
</script>

<template>
  <p v-if="isLoading">Loading session…</p>
  <p v-else-if="isError">{{ error.message }}</p>
  <pre v-else>{{ session }}</pre>
</template>

<!-- Why this works
1. useQuery caches the request under the key ['session'].
2. select shrinks the payload to { id, email, role }, reducing reactivity cost.
3. onSuccess writes the selected data once into Pinia so every consumer of useSessionStore() stays in sync.
4. Loading & error states are exposed for better UX.
5. Query options show production-ready defaults (1-min stale, retry once, no refetch on focus). -->

