import React from "react";
import FieldDropDown from "lib/hookForm/fieldDropDown";
import { ICompanyLogo } from "services/api/company/companyTypes";
import apiLoanQuery from "services/api/loan/apiLoanQuery";

interface IProps {
  /** Loan GUID that determines which logos to fetch */
  forcePlaceLoanGuid?: string;
  /** Optional default logo to pre-select */
  companyGuid?: string;
}

const LoanLogoDropdown: React.FC<IProps> = ({ forcePlaceLoanGuid, companyGuid }) => {
  // Skip the query entirely when no loan GUID is supplied.
  const {
    data: companyLogos,
    isLoading,
    isError,
    error,
  } = apiLoanQuery.useGetCompanyLogosInfoByLoanGuidQuery(forcePlaceLoanGuid!, {
    skip: !forcePlaceLoanGuid,
  });

  // No GUID → nothing to show or fetch.
  if (!forcePlaceLoanGuid) return null;

  if (isLoading) {
    return <span>Loading company logos…</span>;
  }

  if (isError) {
    console.error("LoanLogoDropdown error", error);
    return <span>Unable to load company logos.</span>;
  }

  // Empty data set → disabled dropdown with explanatory text.
  if (!companyLogos || companyLogos.length === 0) {
    return (
      <FieldDropDown
        label="Company Logo"
        name="portfolioIdentifier"
        data={[]}
        placeholder="No logos available"
        disabled
        labelColSize={3}
        inputColSize={9}
      />
    );
  }

  // Transform API payload into dropdown-friendly structure.
  const logoKeyValues = companyLogos.map((logo: ICompanyLogo) => ({
    key: logo.portfolioIdentifier,
    value: logo.logoDescription || "Unnamed Logo",
  }));

  return (
    <FieldDropDown
      label="Company Logo"
      name="portfolioIdentifier"
      data={logoKeyValues}
      placeholder="Select Logo"
      labelColSize={3}
      inputColSize={9}
      defaultValue={companyGuid}
      aria-label="Company logo selector"
    />
  );
};

export default LoanLogoDropdown;

