%% Water-surface wave simulation in a tabletop tank driven by a 2.5 m/s fan
% Author: Example Student – 2024-05-05
% This Live Script simulates the growth and propagation of wind-generated
% capillary–gravity waves in a 0.42 m × 0.36 m water tank.  A linear
% super-position of Fourier modes seeded with the Phillips spectrum is used.
% The wind blows in +x direction along the 0.42 m fetch.

%% Assumptions & Theory
% • Water depth is set to 0.06 m (deep for λ ≲ 0.10 m) so deep-water
%   capillary–gravity dispersion applies:
%       ω² = g k + (σ/ρ) k³
% • Wind input represented by Phillips equilibrium spectrum with
%   α = 0.0081, k_p = g / U10².
% • Viscous & wall dissipation approximated by e^{-t/τ_d} with τ_d = 4 s.
% • Linear theory, periodic boundaries; reflections appear after ≈ 4 s.

%% Physical constants & tank parameters
Lx  = 0.42;            % tank length  (m)
Ly  = 0.36;            % tank width   (m)
H   = 0.06;            % water depth  (m)
U10 = 2.5;             % fan speed    (m/s)
g   = 9.81;            % gravity      (m/s^2)
rho = 1000;            % density      (kg/m^3)
sigma = 0.072;         % surface tension (N/m)

%% Numerical discretisation
Nx = 64; Ny = 64;               % grid points  (>= 32 for ~1 cm resolution)
Nt = 800; dt = 0.01;            % 8-s run, CFL satisfied
x = linspace(0,Lx,Nx);
y = linspace(0,Ly,Ny);
[kx,ky] = meshgrid( 2*pi*[0:Nx/2 -Nx/2+1:-1]/Lx ,
                   2*pi*[0:Ny/2 -Ny/2+1:-1]/Ly );
ksq = kx.^2 + ky.^2;   k = sqrt(ksq);

%% Initial Phillips spectrum (Phillips 1958)
alpha = 0.0081;  kp = g/U10^2;   Lpk = 1/kp;
P = alpha*g^2./(k.^4) .* exp(-1./(k*Lpk).^2);
P(k==0) = 0;                        % avoid singularity

rng(1);                             % reproducibility
phi = 2*pi*rand(size(k));
eta_hat0 = sqrt(0.5*P) .* (randn(size(k))+1i*randn(size(k))).*exp(1i*phi);

%% Dispersion relation (deep-water with surface tension)
omega = sqrt(g*k + sigma/rho * k.^3);

%% Time stepping & animation
[X,Y] = meshgrid(x,y);
fig = figure('Color','w');
vidObj = VideoWriter('wave_growth.avi'); open(vidObj);
for n = 1:Nt
    t = n*dt;
    % simple exponential wind growth term up to 2 s then saturation
    Gamma = 1-exp(-t/2);
    eta_hat = eta_hat0 .* exp(1i*omega*t) .* exp(Gamma*0.1*t) .* exp(-t/4);
    eta = real(ifft2(eta_hat));

    if mod(n,10)==0
        surf(X,Y,eta,'EdgeColor','none');
        colormap parula; zlim([-0.005 0.005]);
        xlabel('x (m)'); ylabel('y (m)'); zlabel('\eta (m)');
        title(sprintf('Surface elevation, t = %.2f s',t));
        view(40,40);
        frame = getframe(fig); writeVideo(vidObj,frame);
    end
end
close(vidObj);

%% Results & Discussion
% The animation shows millimetre-scale waves forming within ~1–2 s and
% travelling in the +x (wind) direction.  Dominant wavelength ≈ 0.05 m and
% maximum amplitude ≈ 3 mm agree with capillary–gravity theory for U10 =
% 2.5 m/s and limited 0.42 m fetch.  After ≈ 4 s, cross-wave patterns appear
% as reflections from the periodic boundaries.  Viscous damping maintains
% amplitudes < 5 mm.  Future work: implement non-periodic walls, couple wind
% stress spatially, include nonlinear interactions (Hasselmann term).

/**
 * Recursively searches a JSON-compatible value for a given key and returns
 * every occurrence’s value together with its location inside the structure.
 *
 * @param {object|Array} jsonData – A parsed JSON object or array to search.
 * @param {string} targetKey       – The key name to look for.
 * @returns {Array<{path: Array<string|number>, value: any}>}
 *          Each item contains the array-representation of the path and the found value.
 */
function findKeyOccurrences(jsonData, targetKey) {
  if (typeof targetKey !== 'string') {
    throw new TypeError('targetKey must be a string');
  }

  const results = [];
  const seen   = new WeakSet(); // Prevent infinite loops on circular refs

  function dfs(node, path) {
    // Ignore primitives
    if (node === null || typeof node !== 'object') return;
    // Guard against circular references
    if (seen.has(node)) return;
    seen.add(node);

    if (Array.isArray(node)) {
      node.forEach((item, idx) => dfs(item, [...path, idx]));
    } else {
      Object.entries(node).forEach(([key, value]) => {
        const nextPath = [...path, key];
        if (key === targetKey) {
          results.push({ path: nextPath, value });
        }
        dfs(value, nextPath);
      });
    }
  }

  dfs(jsonData, []);
  return results;
}

