my ($quality, $preset, $resize, $noise, $help);
GetOptions(
    'quality|q=i' => \$quality,
    'preset|p=i'  => \$preset,
    'resize|r=i'  => \$resize,
    'noise|n=i'   => \$noise,
    'help|h'      => \$help,
) or usage();

usage() if $help;
my $input_file = shift @ARGV // usage();
usage() unless defined $quality && defined $preset;

die "FILE NOT FOUND: $input_file\n" unless -f $input_file;

# ---------- Paths & metadata ----------
my $file_path = abs_path($input_file);
(my $file_name = basename($file_path)) =~ s/\.[^.]+$//;   # strip extension
my $chunk_method = 'ffms2';
$noise //= 10;

my $output_name = sprintf '%s.reencode.av1an.aom.rf%s.p%s',
                        $file_name, $quality, $preset;
$output_name .= ".noise$noise" if defined $noise;
$output_name .= ".${resize}p"  if defined $resize;

my $metadata_comment = "reencoded with av1an(aom), 10-bit, cpu-used=${preset}, cq=${quality}, chunk-method=$chunk_method";

# ---------- Raise open-file limit ----------
system('ulimit', '-n', '2048') == 0 or warn "Unable to raise ulimit (non-fatal)";

# ---------- Build and run av1an ----------
my $threads = 2;
my $ffmpeg_sub = " -an" . (defined $resize ? qq{ -vf 'scale=-1:${resize}'} : '');

my @av1an_cmd = (
    'av1an', '--verbose',
    '-i',  $file_path,
    '--encoder', 'aom',
    '--workers', 4,
    '--resume',
    '--extra-split', 300,
    '--ignore-frame-mismatch',
    '--audio-params', ' -an ',
    '--ffmpeg', $ffmpeg_sub,
    '--split-method', 'av-scenechange',
    '--chunk-method', $chunk_method,
    '--concat', 'mkvmerge',
    "--set-thread-affinity=$threads",
    "--photon-noise=$noise",
    '--video-params', join(' ',
        '--bit-depth=10',
        "--threads=$threads",
        "--end-usage=q --cq-level=$quality --cpu-used=$preset",
        '--tile-columns=0 --tile-rows=0',
        '--tune-content=psy --tune=ssim',
        '--lag-in-frames=64',
        '--enable-keyframe-filtering=1 --disable-kf --kf-max-dist=9999',
        '--enable-qm=1 --deltaq-mode=0 --aq-mode=0 --quant-b-adapt=1',
        '--enable-fwd-kf=0 --arnr-strength=4 --sb-size=dynamic --enable-dnl-denoising=0',
    ),
    '-o', "${output_name}.audioless.mkv",
);
