Here is an implementation that satisfies the requirements and demonstrates its use.

```javascript
// Recursive retry without async/await
function requestWithRetry(requestFn, retries = 3) {
  if (typeof requestFn !== "function") {
    throw new TypeError("requestFn must be a function returning a Promise");
  }

  return new Promise((resolve, reject) => {
    function attempt(remaining) {
      try {
        requestFn()
          .then(resolve) // succeed → bubble the value out
          .catch((err) => {
            if (remaining === 0) {
              // out of retries → reject
              reject(err);
            } else {
              attempt(remaining - 1); // recurse
            }
          });
      } catch (syncErr) {
        // requestFn threw synchronously (e.g., bad input)
        if (remaining === 0) {
          reject(syncErr);
        } else {
          attempt(remaining - 1);
        }
      }
    }

    attempt(retries);
  });
}

// Example usage:
let count = 0;
const flaky = () => {
  count++;
  return count === 3 ? Promise.resolve("OK on attempt " + count) : Promise.reject(new Error("fail " + count));
};

requestWithRetry(flaky)
  .then((val) => console.log("Resolved:", val))
  .catch((err) => console.error("Rejected after 3 tries:", err.message));
```

Explanation: `attempt` calls `requestFn` and, on rejection or synchronous throw, decrements `remaining` and calls itself again until `remaining` hits 0. Because the helper returns/forwards the same promise chain, callers receive the first successful value or the final error. No `await` or loops are used.

