"""Connect-4 (Human vs AI)
Author: Jane Doe – All code original except where noted.
Python 3.9+, no external dependencies.
Run:  python connect4.py  [--depth 4]  # optional search depth
Quit: press ‘q’ during your move or Ctrl-C.
"""
import math, random, sys, argparse
from typing import List, Tuple, Optional

ROW_COUNT, COLUMN_COUNT = 6, 7
EMPTY, PLAYER, AI = 0, 1, 2
WIN_LEN = 4
DEFAULT_DEPTH = 4

# ───────── Board helpers ─────────

def create_board() -> List[List[int]]:
    return [[EMPTY for _ in range(COLUMN_COUNT)] for _ in range(ROW_COUNT)]

def valid_cols(board):
    return [c for c in range(COLUMN_COUNT) if board[0][c] == EMPTY]

def next_row(board, col):
    for r in range(ROW_COUNT - 1, -1, -1):
        if board[r][col] == EMPTY:
            return r
    raise ValueError("Column full")

def drop(board, row, col, piece):
    board[row][col] = piece

# ───────── Win / draw detection ─────────

def wins(board, piece) -> bool:
    # horiz & vert
    for r in range(ROW_COUNT):
        for c in range(COLUMN_COUNT - 3):
            if all(board[r][c+i] == piece for i in range(WIN_LEN)):
                return True
    for c in range(COLUMN_COUNT):
        for r in range(ROW_COUNT - 3):
            if all(board[r+i][c] == piece for i in range(WIN_LEN)):
                return True
    # positive diag /
    for r in range(ROW_COUNT - 3):
        for c in range(COLUMN_COUNT - 3):
            if all(board[r+i][c+i] == piece for i in range(WIN_LEN)):
                return True
    # negative diag \
    for r in range(3, ROW_COUNT):
        for c in range(COLUMN_COUNT - 3):
            if all(board[r-i][c+i] == piece for i in range(WIN_LEN)):
                return True
    return False

def draw(board):
    return all(board[0][c] != EMPTY for c in range(COLUMN_COUNT))

# ───────── Evaluation for minimax ─────────

def score_window(win: List[int], piece: int):
    opp = PLAYER if piece == AI else AI
    if win.count(piece) == 4:  return 100
    if win.count(piece) == 3 and win.count(EMPTY) == 1: return 5
    if win.count(piece) == 2 and win.count(EMPTY) == 2: return 2
    if win.count(opp) == 3 and win.count(EMPTY) == 1: return -4
    return 0

def evaluate(board, piece):
    s = 0
    # center preference
    center = [board[r][COLUMN_COUNT//2] for r in range(ROW_COUNT)].count(piece)
    s += center * 3
    # horizontal, vertical, diags
    for r in range(ROW_COUNT):
        row = [board[r][c] for c in range(COLUMN_COUNT)]
        for c in range(COLUMN_COUNT-3):
            s += score_window(row[c:c+WIN_LEN], piece)
    for c in range(COLUMN_COUNT):
        col = [board[r][c] for r in range(ROW_COUNT)]
        for r in range(ROW_COUNT-3):
            s += score_window(col[r:r+WIN_LEN], piece)
    for r in range(ROW_COUNT-3):
        for c in range(COLUMN_COUNT-3):
            s += score_window([board[r+i][c+i] for i in range(WIN_LEN)], piece)
    for r in range(ROW_COUNT-3):
        for c in range(COLUMN_COUNT-3):
            s += score_window([board[r+3-i][c+i] for i in range(WIN_LEN)], piece)
    return s

def terminal(board):
    return wins(board, PLAYER) or wins(board, AI) or draw(board)

def minimax(board, depth, alpha, beta, max_player):
    if depth == 0 or terminal(board):
        if wins(board, AI):
            return (None, math.inf)
        if wins(board, PLAYER):
            return (None, -math.inf)
        if draw(board):
            return (None, 0)
        return (None, evaluate(board, AI))
    columns = valid_cols(board)
    best_col = random.choice(columns)
    if max_player:
        value = -math.inf
        for col in columns:
            row = next_row(board, col)
            b2 = [r.copy() for r in board]
            drop(b2, row, col, AI)
            _, score = minimax(b2, depth-1, alpha, beta, False)
            if score > value:
                value, best_col = score, col
            alpha = max(alpha, value)
            if alpha >= beta:
                break
        return best_col, value
    else:
        value = math.inf
        for col in columns:
            row = next_row(board, col)
            b2 = [r.copy() for r in board]
            drop(b2, row, col, PLAYER)
            _, score = minimax(b2, depth-1, alpha, beta, True)
            if score < value:
                value, best_col = score, col
            beta = min(beta, value)
            if alpha >= beta:
                break
        return best_col, value

# ───────── Display ─────────

def show(board):
    print("\n 0 1 2 3 4 5 6")
    for r in range(ROW_COUNT):
        print("|" + "|".join(" .XO"[board[r][c]] for c in range(COLUMN_COUNT)) + "|")
    print(" ───────────────")

# ───────── Main game loop ─────────

def play(depth):
    board = create_board()
    player_turn = random.choice([True, False])
    print("Welcome to Connect-4 – you are X, AI is O. Type 0-6 or 'q' to quit.")
    show(board)
    while True:
        if player_turn:
            move = input("Your move: ")
            if move.lower().startswith('q'):
                print("Bye!"); return
            if not move.isdigit() or int(move) not in range(COLUMN_COUNT):
                print("Enter a number 0-6."); continue
            col = int(move)
            if col not in valid_cols(board):
                print("That column is full."); continue
            row = next_row(board, col)
            drop(board, row, col, PLAYER)
            if wins(board, PLAYER):
                show(board); print("You win!"); return
            if draw(board):
                show(board); print("Draw!"); return
        else:
            col, _ = minimax(board, depth, -math.inf, math.inf, True)
            row = next_row(board, col)
            drop(board, row, col, AI)
            print(f"AI picks {col}")
            if wins(board, AI):
                show(board); print("AI wins!"); return
            if draw(board):
                show(board); print("Draw!"); return
        player_turn = not player_turn
        show(board)

if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--depth", type=int, default=DEFAULT_DEPTH, help="search depth 1-6")
    args = parser.parse_args()
    try:
        play(args.depth)
    except KeyboardInterrupt:
        print("\nGame interrupted. Goodbye!")

