import UIKit
import Messages

final class MessagesViewController: MSMessagesAppViewController {
    // MARK: – Lifecycle
    override func willBecomeActive(with conversation: MSConversation) {
        super.willBecomeActive(with: conversation)
        configureUI()
    }

    // MARK: – UI
    private func configureUI() {
        // Remove anything we may have added previously (compact ▶︎ expanded transitions)
        view.subviews.forEach { $0.removeFromSuperview() }

        // Create the two buttons
        let helloButton = makeButton(title: "Hello", action: #selector(sendHello))
        let worldButton = makeButton(title: "World", action: #selector(sendWorld))

        // Put them in a horizontal stack view so they resize nicely on all devices
        let stack = UIStackView(arrangedSubviews: [helloButton, worldButton])
        stack.axis = .horizontal
        stack.spacing = 12
        stack.distribution = .fillEqually
        stack.translatesAutoresizingMaskIntoConstraints = false
        view.addSubview(stack)

        // Auto Layout ‑ center horizontally & vertically in compact view
        NSLayoutConstraint.activate([
            stack.centerXAnchor.constraint(equalTo: view.centerXAnchor),
            stack.centerYAnchor.constraint(equalTo: view.centerYAnchor),
            stack.heightAnchor.constraint(equalToConstant: 44),
            stack.leadingAnchor.constraint(greaterThanOrEqualTo: view.leadingAnchor, constant: 8),
            stack.trailingAnchor.constraint(lessThanOrEqualTo: view.trailingAnchor, constant: -8)
        ])
    }

    private func makeButton(title: String, action: Selector) -> UIButton {
        let button = UIButton(type: .system)
        button.setTitle(title, for: .normal)
        button.titleLabel?.font = .systemFont(ofSize: 17, weight: .medium)
        button.backgroundColor = UIColor.systemBlue.withAlphaComponent(0.15)
        button.layer.cornerRadius = 8
        button.addTarget(self, action: action, for: .touchUpInside)
        button.accessibilityLabel = "Send \(title)" // accessibility
        return button
    }

    // MARK: – Actions
    @objc private func sendHello() { send(text: "Hello") }
    @objc private func sendWorld() { send(text: "World") }

    private func send(text: String) {
