async function downloadPage(url = location.href) {
  try {
    // ---- Fetch the resource ----
    const response = await fetch(url, { mode: 'cors' });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);

    // ---- Convert to Blob ----
    const mime = response.headers.get('Content-Type') || 'text/html;charset=UTF-8';
    const data = await response.blob(); // works for HTML, images, PDFs, etc.

    // ---- Create download link ----
    const filename = new URL(url).hostname.replace(/[^\w.-]/g, '_') + '.html';
    const a = document.createElement('a');
    a.href = URL.createObjectURL(new Blob([data], { type: mime }));
    a.download = filename;
    a.style.display = 'none';
    document.body.appendChild(a);
    a.click();

    // ---- Clean up ----
    URL.revokeObjectURL(a.href);
    a.remove();
  } catch (err) {
    console.error('Download failed:', err, '\nTip: If the console shows a CORS error, try a proxy like https://r.jina.ai/http://<your-url> or run from a browser extension context.');
  }
}

/*
WHY THIS WORKS (short version)
1. fetch() downloads the raw bytes; {mode:'cors'} lets us detect cross-origin blocks.
2. The body is read as a Blob so binary data remains unchanged.
3. URL.createObjectURL() turns that Blob into a local pseudo-URL.
4. We attach that URL to an invisible <a download> element and click it; the browser shows its save dialog.
5. Finally revoke the object URL to avoid memory leaks.

COMMON PITFALLS & TIPS
• CORS: If the remote site does NOT send   Access-Control-Allow-Origin: * , the browser will refuse to give us the body. Use a public CORS proxy, your own backend, or run the snippet from an extension where CORS is relaxed.
• Large files (>100 MB) can consume memory; for very large assets, consider streaming to IndexedDB or using Response.body as a ReadableStream.
• Pop-up blockers do not interfere because the click is user-generated via script.
• Want JSON?  Change the MIME type to 'application/json' and the extension to .json.

EXAMPLE VARIATION: Download a JSON API response
