})();

SECURITY & ETHICS
• Do not scrape pay-walled or private content without permission.
• Avoid untrusted schemes (javascript:, file:).  Always virus-scan files you download.
• This snippet revokes object URLs and removes temporary DOM nodes to keep memory usage low.

✔ Done — paste, call, and you have an offline copy of any CORS-friendly page!

--- src/main.rs ---
use clap::{Arg, Command};
use std::fs::File;
use std::io::{BufRead, BufReader};
use std::process::Command as ProcessCommand;
use url::Url;

const YT_DOMAINS: &[&str] = &[
    "youtube.com",
    "www.youtube.com",
    "m.youtube.com",
    "youtu.be",
    "www.youtu.be",
    "youtube-nocookie.com",
];

fn is_youtube(url: &Url) -> bool {
    url.domain()
        .map(|d| YT_DOMAINS.contains(&d))
        .unwrap_or(false)
}

fn main() -> anyhow::Result<()> {
    let cli = Command::new("yt-filter-dl")
        .version("0.1.0")
        .about("Reads URLs from a file, filters out YouTube links and downloads them with yt-dlp")
        .arg(
            Arg::new("input")
                .required(true)
                .help("Path to the text file containing one URL per line"),
        )
        .arg(
            Arg::new("dry-run")
                .long("dry-run")
                .short('n')
                .help("Print what would be downloaded without calling yt-dlp"),
        )
        .get_matches();

    let path = cli.get_one::<String>("input").unwrap();
    let dry_run = cli.get_flag("dry-run");

    let reader = BufReader::new(File::open(path)?);
    let mut youtube = Vec::new();
    let mut others = Vec::new();

    for line in reader.lines() {
        let raw = line?;
        let trimmed = raw.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        match Url::parse(trimmed) {
            Ok(u) if is_youtube(&u) => youtube.push(trimmed.to_owned()),
            Ok(_) => others.push(trimmed.to_owned()),
            Err(_) => eprintln!("Skipping invalid URL: {trimmed}"),
        }
    }

    println!("Found {} YouTube URL(s) and {} non-YouTube URL(s).", youtube.len(), others.len());

    if dry_run {
        for u in &youtube {
            println!("Would download {u}");
        }
        return Ok(());
    }

    for u in &youtube {
        println!("Downloading {u} …");
        let status = ProcessCommand::new("yt-dlp").arg("--no-mtime").arg(u).status()?;
        if !status.success() {
            eprintln!("yt-dlp reported an error for {u}");
        }
    }

    Ok(())
}

--- Cargo.toml ---
[package]
name = "yt-filter-dl"
version = "0.1.0"
edition = "2021"

[dependencies]
clap = { version = "4.3", features = ["derive"] }
url = "2.4"
anyhow = "1.0"

--- README excerpt ---
# Build
$ cargo build --release

# Usage
$ ./target/release/yt-filter-dl urls.txt        # normal mode
$ ./target/release/yt-filter-dl -n urls.txt     # dry-run

The tool expects yt-dlp to be available in your $PATH. Each URL must be on its own line; blank lines and lines beginning with '#' are ignored.

--- Tests ---
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn youtube_detection() {
        let cases = [
            ("https://www.youtube.com/watch?v=dQw4w9WgXcQ", true),
            ("https://youtu.be/abc", true),
            ("https://example.com", false),
        ];
        for (raw, expect) in cases {
            let url = Url::parse(raw).unwrap();
            assert_eq!(is_youtube(&url), expect);
        }
    }
}

/*
 * Example: .NET 6 console app that posts JSON to https://example.com/api/endpoint
 * A client certificate (client.pfx) with password is attached to the request.
 * NOTE: Replace certPath, certPassword, and request URI with real values in production.
 */

using System;
using System.Net.Http;
using System.Security.Authentication;
using System.Security.Cryptography.X509Certificates;
using System.Text;
using System.Threading.Tasks;

namespace ClientCertPostExample
{
    internal class Program
    {
        // C# 9 / .NET 5+ allows async Main
        private static async Task Main()
        {
            const string certPath = "client.pfx";        // <-- path to your .pfx file
            const string certPassword = "p@ssw0rd";      // <-- NEVER hard-code in production!

            // Load the certificate (must include private key)
            var cert = new X509Certificate2(
                certPath,
                certPassword,
                X509KeyStorageFlags.MachineKeySet | X509KeyStorageFlags.EphemeralKeySet);

            // Create a handler and attach the client certificate
            using var handler = new HttpClientHandler();
            handler.ClientCertificates.Add(cert);
            handler.SslProtocols = SslProtocols.Tls12; // optional but recommended

            using var client = new HttpClient(handler)
            {
                BaseAddress = new Uri("https://example.com")
            };

            // JSON body to send
            using var content = new StringContent("{ \"data\": \"value\" }", Encoding.UTF8, "application/json");

            try
            {
                HttpResponseMessage response = await client.PostAsync("/api/endpoint", content);
                response.EnsureSuccessStatusCode();

                string responseBody = await response.Content.ReadAsStringAsync();
                Console.WriteLine("Server responded with:\n" + responseBody);
            }
            catch (HttpRequestException ex)
            {
                Console.Error.WriteLine($"Request failed: {ex.Message}");
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;

public static class HashtagHelper
{
    /// <summary>
    /// Extracts all hashtags from <paramref name="text"/> without the leading '#'.
    /// A hashtag is defined as a '#' that is either at the beginning of the string
    /// or preceded by whitespace, followed by one or more Unicode letters, digits
    /// or underscores. Accented and non-Latin letters are supported via \p{L}.
    /// </summary>
    /// <param name="text">Input text that may contain hashtags.</param>
    /// <returns>List of hashtags in order of appearance; empty list if none.</returns>
    public static List<string> ExtractHashtags(string text)
    {
        if (string.IsNullOrWhiteSpace(text))
            return new List<string>();

        // (?<=^|\s)   — hashtag must be start of string or whitespace-delimited
        // #           — literal hash sign
        // ([\p{L}\p{N}_]+) — capture 1+: letters, numbers or underscore
        var pattern = "(?<=^|\\s)#([\\p{L}\\p{N}_]+)";
        var matches = Regex.Matches(text, pattern, RegexOptions.Compiled);
        return matches.Cast<Match>()
                      .Select(m => m.Groups[1].Value)
                      .ToList();
    }

    // Example usage
    public static void Main()
    {
        string sample = "Here is #CSharp code! #100DaysOfCode,#dotnet; and #Привет #CSharp";
        var tags = ExtractHashtags(sample);
        Console.WriteLine(string.Join(", ", tags));
        // Output: CSharp, 100DaysOfCode, dotnet, Привет, CSharp
    }
}

Why this works
---------------
1. **Regex breakdown**: `(?<=^|\s)` ensures the `#` is either at the very start or preceded by whitespace, preventing false positives such as `email#fail`.  `[\p{L}\p{N}_]+` captures letters (any language), digits, or underscores, thus `#Café`, `#Привет`, and `#100DaysOfCode` all match.
2. **Unicode support**: `\p{L}` covers letters in all scripts.
3. **Performance**: `RegexOptions.Compiled` avoids repeated recompilation in hot paths; for extremely high volume, compile once and reuse.
4. **Edge cases handled**:
   • Beginning or end of string: `#Start` / `#End!`.
   • Trailing punctuation: `#tag!` → `tag`.
   • Duplicate tags retained (can easily `Distinct()` if unique list is desired).
   • Null/empty/whitespace input safely returns empty list.
5. **Tests**
| Input | Expected result |
|-------|-----------------|
| "#hi" | ["hi"] |
| "No tags" | [] |
| "Mix #one, #two.#three" | ["one","two","three"] |
| "camel#inside" | [] |
| "#Привет #123 _#oops_" | ["Привет","123"] |

To deduplicate: `var unique = ExtractHashtags(text).Distinct(StringComparer.OrdinalIgnoreCase);`

